def round_half_to_even(n):
    if isinstance(n, int):
        return n
    else:
        integer_part = int(n)
        fractional_part = n - integer_part
        if fractional_part == 0.5:
            return integer_part + (1 if integer_part % 2 == 0 else 2)
        else:
            return round(n)

