def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    def wrapper(func):
        cache = OrderedDict()
        sentinel = object()

        @wraps(func)
        def cached_func(*args, **kwargs):
            key = args if not typed else (func, args, tuple(kwargs.items()))
            if key not in cache:
                value = func(*args, **kwargs)
                cache[key] = value, timer()
                if len(cache) > maxsize:
                    cache.popitem(last=False)
            else:
                value, last_accessed = cache[key]
                if (timer() - last_accessed) > ttl:
                    cache.pop(key)
                    value = func(*args, **kwargs)
                    cache[key] = value, timer()
                else:
                    key = (func, args, tuple(kwargs.items())) if typed else args
                    value, _ = cache[key]
            return value

        return cached_func

    return wrapper

