def lru_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        hits = misses = 0

        def wrapper(*args, **kwds):
            nonlocal hits, misses
            key = args if not typed else (func, args, kwds)
            if key in cache:
                hits += 1
                return cache[key]
            misses += 1
            result = func(*args, **kwds)
            cache[key] = result
            if len(cache) > maxsize:
                cache.popitem()
            return result

        wrapper.cache_info = lambda: (hits, misses, maxsize, len(cache))
        wrapper.cache_clear = lambda: (cache.clear(), setattr(wrapper, 'hits', 0), setattr(wrapper, 'misses', 0))
        return wrapper

    return decorator

