def minimalBases(classes):
    while True:
        changed = False
        for i in range(len(classes)):
            for j in range(len(classes)):
                if i != j and classes[i].issubset(classes[j]):
                    classes[i] = None
                    changed = True
        classes = [c for c in classes if c is not None]
        if not changed:
            break
    return classes

