def hist_to_graph(hist, make_value=None, get_coordinate="left", field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    coordinate_mapping = {
        "left": lambda x: x[0],
        "right": lambda x: x[1],
        "middle": lambda x: (x[0] + x[1]) / 2
    }

    if get_coordinate not in coordinate_mapping:
        raise ValueError("Invalid get_coordinate option")

    coordinates_func = coordinate_mapping[get_coordinate]

    graph_data = []
    for bin_ in hist.bins:
        coordinates = (bin_.x_min, bin_.x_max)
        value = make_value(bin_)
        if isinstance(value, tuple):
            value = value + coordinates_func(coordinates),
        else:
            value = (value, coordinates_func(coordinates))
        graph_data.append(value)

    graph = {
        "data": graph_data,
        "field_names": field_names
    }

    if scale is True:
        graph["scale"] = hist.scale

    return graph

